import ctypes

class gsl_sf_result_e10(ctypes.Structure):
    _fields_ = [('val', ctypes.c_double), ('err', ctypes.c_double), ('e10', ctypes.c_double)]

class gsl_sf_result(ctypes.Structure):
    _fields_ = [('val', ctypes.c_double), ('err', ctypes.c_double)]

def smash_result(input_dict: dict) -> dict:
  libgslcblas = ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
  gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')
  input_struct = gsl_sf_result_e10(**input_dict)
  output_struct = gsl_sf_result()
  result = libgslcblas.gsl_sf_result_smash_e(input_struct, output_struct)
  if result != 0:
    raise ctypes.WinError(result)
  return {'val': output_struct.val, 'err': output_struct.err}

