from typing import List, Union

ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class gsl_combination(object):
    def __init__(self, n: int, k: int) -> None:
        self._handle = gsl.gsl_combination_alloc(n, k)
        if self._handle == ctypes.c_void_p(0):
            raise MemoryError("Combination allocation failed.")

def create_first_combination(n: int, k: int) -> List[int]:
        comb = gsl_combination(n, k)
        result = (ctypes.c_int * k)()  # Create a list of integers
        gsl.gsl_combination_init_first(comb._handle, result)
        return [result[i] for i in range(k)]

def __del__(self) -> None:
        gsl.gsl_combination_free(self._handle)

