def copy_matrix(source, destination):
    libgslcblas = ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')
    source_ptr = (ctypes.c_double * (len(source) * len(source[0])))() 
    for i in range(len(source)):
        for j in range(len(source[0])):
            source_ptr[i * len(source[0]) + j] = source[i][j]
    destination_ptr = (ctypes.c_double * (len(destination) * len(destination[0])))()
    libgslcblas.copy_matrix.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), len(source) * len(source[0])]
    libgslcblas.copy_matrix(source_ptr, destination_ptr, len(source) * len(source[0]))
    for i in range(len(destination)):
        for j in range(len(destination[0])):
            destination[i][j] = destination_ptr[i * len(destination[0]) + j]
    return destination

