class GSLMatrix(object):
    def __init__(self, data):
        self.data = data
    def get_array(self):
        return (ctypes.c_float * len(self.data[0]))(*self.data[0])
    def get_matrix(self):
        return gsl.gsl_matrix_alloc(len(self.data), len(self.data[0]))
    def set_elements(self):
        for i in range(len(self.data)):
            for j in range(len(self.data[0])):
                self.get_matrix().set(i, j, self.data[i][j])
def find_minmax_indices(matrix):
    gsl_matrix = GSLMatrix(matrix).get_matrix()
gsl_matrix.set_elements()
    rows = (ctypes.c_int * len(matrix)).from_list([row for row in matrix])
    cols = (ctypes.c_int * len(matrix[0])).from_list([col for col in range(len(matrix[0]))])
    min_row = ctypes.c_int()
    min_col = ctypes.c_int()
    max_row = ctypes.c_int() 
    max_col = ctypes.c_int()
    gsl.gsl_matrix_minmax_index(gsl_matrix, min_row, min_col, max_row, max_col)
    return (min_row.value, min_col.value, max_row.value, max_col.value)

