# Define function prototypes
class GSLFunction(object):
    def __init__(self, func):
        self.func = func
    def __call__(self, x, params=None):
        if params is None:
            return self.func(x)
        else:
            return self.func(x, *params)

class GSLMinFMinimizer(object):
    def __init__(self, type):
        self.type = type
    def iterate(self, func, x_minimum, f_minimum, x_lower, f_lower, x_upper, f_upper, iter_count=100):
        # Initialize state structure
        state = gsl.gsl_min_fminimizer_alloc(self.type)

        # Set function and initial values
        func_ptr = func.__call__
        gsl.gsl_min_fminimizer_set(state, func_ptr, x_minimum, f_minimum, x_lower, f_lower, x_upper, f_upper)

        # Iterate until convergence or maximum iterations
        for i in range(iter_count):
            gsl.gsl_min_fminimizer_iterate(state)
            # Check for convergence
            if gsl.gsl_min_fminimizer_status(state) == 0:
                break

        # Retrieve updated values
        x_minimum = c_double(gsl.gsl_min_fminimizer_x_minimum(state))
        f_minimum = c_double(gsl.gsl_min_fminimizer_f_minimum(state))
        x_lower = c_double(gsl.gsl_min_fminimizer_x_lower(state))
        f_lower = c_double(gsl.gsl_min_fminimizer_f_lower(state))
        x_upper = c_double(gsl.gsl_min_fminimizer_x_upper(state))
        f_upper = c_double(gsl.gsl_min_fminimizer_f_upper(state))

        # Free state structure
        gsl.gsl_min_fminimizer_free(state)

        return x_minimum, f_minimum, x_lower, f_lower, x_upper, f_upper

