def transpose_matrix(matrix):
    libgslcblas = ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')
    class GSLMatrix:
        def __init__(self, num_rows, num_cols):
            self.num_rows = num_rows
            self.num_cols = num_cols
            self.data = (ctypes.c_double * (num_rows * num_cols))()
    m = GSLMatrix(len(matrix), len(matrix[0]))
    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            m.data[i * len(matrix[0]) + j] = matrix[i][j]
    gsl.gsl_matrix_transpose(ctypes.cast(m.data, ctypes.POINTER(ctypes.c_double)), m.num_rows, m.num_cols)
    transposed_matrix = [[0 for _ in range(m.num_rows)] for _ in range(m.num_cols)]
    for i in range(m.num_rows):
        for j in range(m.num_cols):
            transposed_matrix[j][i] = m.data[i * m.num_cols + j]
    return transposed_matrix

