class RingBuf(ctypes.Structure):
  _fields_ =
    [('size', ctypes.c_int), ('values', ctypes.POINTER(ctypes.c_double))]

def initialize_ringbuf(size: int) -> RingBuf:
  ringbuf = RingBuf() 
  ringbuf.size = size
  ringbuf.values = (ctypes.cast(ctypes.create_string_buffer(size * ctypes.sizeof(ctypes.c_double)), ctypes.POINTER(ctypes.c_double)))
  return ringbuf
def insert_into_ringbuf(ringbuf: RingBuf, values: list) -> None:
  for value in values:
    gsl.gsl_ringbuf_insert(ringbuf.values, ctypes.c_int(len(ringbuf.values)), ctypes.cast(ctypes.create_string_buffer(ctypes.sizeof(ctypes.c_double)), ctypes.POINTER(ctypes.c_double)), value)

def copy_ringbuf_to_list(ringbuf: RingBuf) -> list:
  return [value for value in (ringbuf.values[:ringbuf.size])]

if __name__ == '__main__':
  try:
    input_values = [1, 2, 3, 4, 5]
    ringbuf = initialize_ringbuf(size=len(input_values))
    insert_into_ringbuf(ringbuf, input_values)
    print(copy_ringbuf_to_list(ringbuf))
  except Exception as e:
    print(f'Error: {e}')

