def dot_product(vector_x, vector_y):
  if len(vector_x) != len(vector_y):
    raise ValueError('Vectors must have the same length.')
  x = (ctypes.c_float * len(vector_x))(*vector_x)
  y = (ctypes.c_float * len(vector_y))(*vector_y)
  return dllcblas.cblas_ddot(len(vector_x), x, 1, y, 1)


