class GslRstatQuantileWorkspace:
    def __init__(self):
        self._workspace = gsl.gsl_rstat_quantile_alloc()

def __del__(self):
        gsl.gsl_rstat_quantile_free(self._workspace)

def add_values(self, values):
        gsl.gsl_rstat_quantile_add(self._workspace, values)

def get_quantile(self, p):
        result = ctypes.c_double()
gsl.gsl_rstat_quantile_get(self._workspace, p, result)
        return result.value

def compute_quantile(p, values):
    workspace = GslRstatQuantileWorkspace()
    for value in values:
        workspace.add_values([value])
    quantile = workspace.get_quantile(p)
    return quantile
if __name__ == "__main__":
    p = 0.5
    values = [1, 2, 3, 4, 5]
    quantile = compute_quantile(p, values)
    print(f"Quantile at {p}: {quantile}")

